export const APP_VERSION=4
export const STORAGE_KEY='tail-room-state-v4'
export const HOUR=3_600_000
export const DAY=24*HOUR
const MINUTE=60_000
const clamp=(v,min=0,max=100)=>Math.min(max,Math.max(min,v))
export const DEFAULT_ROUTINE=Object.freeze({wake:'07:00',breakfast:'07:30',dinner:'19:00',bedtime:'23:30'})
const pattern=/^([01]\d|2[0-3]):[0-5]\d$/
const safeTime=(v,f)=>pattern.test(String(v||''))?String(v):f
export const sanitizeRoutine=(r={})=>({wake:safeTime(r.wake,DEFAULT_ROUTINE.wake),breakfast:safeTime(r.breakfast,DEFAULT_ROUTINE.breakfast),dinner:safeTime(r.dinner,DEFAULT_ROUTINE.dinner),bedtime:safeTime(r.bedtime,DEFAULT_ROUTINE.bedtime)})
export const createInitialState=(now=Date.now())=>({version:APP_VERSION,onboarded:false,kind:'cat',petName:'こむぎ',createdAt:now,lastSeenAt:now,lastFedAt:now,lastPlayedAt:null,lastPettedAt:null,fullness:86,energy:82,comfort:76,bond:12,totalMeals:0,totalPets:0,totalPlays:0,routine:{...DEFAULT_ROUTINE},memories:[],preferences:{favoriteTouchZone:null,touchCounts:{head:0,body:0,tail:0},favoriteFood:null,foodCounts:{daily:0,special:0,treat:0}},debug:{timeOffsetMs:0,forcedHunger:false,forcedSleep:false}})
export const getVirtualNow=(s,now=Date.now())=>now+Number(s?.debug?.timeOffsetMs||0)
export const minutesOfDay=t=>{const[h,m]=safeTime(t,'00:00').split(':').map(Number);return h*60+m}
const localMidnight=t=>{const d=new Date(t);d.setHours(0,0,0,0);return d.getTime()}
export const getTimePhase=(t=Date.now())=>{const h=new Date(t).getHours();return h>=5&&h<10?'morning':h>=10&&h<17?'day':h>=17&&h<21?'evening':'night'}
export const isSleepTime=(r,t=Date.now(),forced=false)=>{if(forced)return true;const s=sanitizeRoutine(r),d=new Date(t),cur=d.getHours()*60+d.getMinutes(),bed=minutesOfDay(s.bedtime),wake=minutesOfDay(s.wake);if(bed===wake)return false;return bed>wake?cur>=bed||cur<wake:cur>=bed&&cur<wake}
export const getDaysTogether=(s,t=Date.now())=>Math.max(1,Math.floor((t-Number(s?.createdAt||t))/DAY)+1)
export const getGrowthStage=(s,t=Date.now())=>{const day=getDaysTogether(s,t);if(day<30)return{id:'baby',label:s?.kind==='dog'?'子犬期':'子猫期',day,progress:day/30};if(day<75)return{id:'growing',label:'育ちざかり',day,progress:(day-30)/45};if(day<120)return{id:'young',label:'若い時期',day,progress:(day-75)/45};return{id:'adult',label:'おとな',day,progress:1}}
export const getMealSchedule=(s,t=Date.now())=>{const r=sanitizeRoutine(s?.routine),mid=localMidnight(t),b=minutesOfDay(r.breakfast)*MINUTE,d=minutesOfDay(r.dinner)*MINUTE;return[{id:'yesterday-dinner',label:'夜ごはん',at:mid-DAY+d},{id:'today-breakfast',label:'朝ごはん',at:mid+b},{id:'today-dinner',label:'夜ごはん',at:mid+d},{id:'tomorrow-breakfast',label:'朝ごはん',at:mid+DAY+b}].sort((a,b)=>a.at-b.at)}
export const getMealStatus=(s,t=Date.now())=>{const schedule=getMealSchedule(s,t),latest=[...schedule].reverse().find(m=>m.at<=t)||null,next=schedule.find(m=>m.at>t)||schedule.at(-1),last=Number(s?.lastFedAt||0),late=latest?Math.max(0,Math.floor((t-latest.at)/MINUTE)):0,forced=Boolean(s?.debug?.forcedHunger),overdue=forced||Boolean(latest&&late>=30&&last<latest.at);return{overdue,minutesLate:forced?Math.max(late,90):late,dueMeal:overdue?latest:null,next,nextInMinutes:Math.max(0,Math.ceil((next.at-t)/MINUTE))}}
const memoryId=(p,t)=>`${p}-${t}-${Math.random().toString(36).slice(2,7)}`
export const addMemory=(s,title,body,t=Date.now(),type='life')=>({...s,memories:[{id:memoryId(type,t),type,title,body,createdAt:t},...(Array.isArray(s.memories)?s.memories:[])].slice(0,60)})
export const beginLife=(s,p,now=Date.now())=>{const base=createInitialState(now),kind=p?.kind==='dog'?'dog':'cat',petName=String(p?.petName||'').trim()||(kind==='dog'?'むぎ':'こむぎ'),next={...base,kind,petName,routine:sanitizeRoutine(p?.routine),onboarded:true,createdAt:now,lastSeenAt:now,lastFedAt:now};return addMemory(next,`${petName}がやってきた日`,'新しい部屋の匂いを確かめながら、あなたの手に少しだけ身体を預けました。',now,'welcome')}
export const applyElapsedTime=(s,now=Date.now())=>{if(!s?.onboarded)return{...s,lastSeenAt:now};const elapsed=Math.max(0,(now-Number(s.lastSeenAt||now))/HOUR);if(elapsed<.01)return{...s,lastSeenAt:now};const sleeping=isSleepTime(s.routine,now,s?.debug?.forcedSleep);let fullness=clamp(Number(s.fullness||0)-elapsed*2.35,18,100),energy=sleeping?clamp(Number(s.energy||0)+elapsed*4.4,28,100):clamp(Number(s.energy||0)-elapsed*.68,28,100),comfort=clamp(Number(s.comfort||0)-elapsed*.28,45,100);const meal=getMealStatus(s,now);if(meal.overdue)fullness=Math.min(fullness,meal.minutesLate>180?34:48);let next={...s,fullness,energy,comfort,lastSeenAt:now};if(elapsed>=5){const key=new Date(now).toISOString().slice(0,10),found=next.memories?.some(x=>x.id.startsWith(`return-${key}`));if(!found){const body=s.kind==='dog'?`${s.petName}は一度寝床で休み、玄関の音に気づくと顔を上げました。`:`${s.petName}は窓辺と寝床を行き来し、あなたの気配に気づいて耳を向けました。`;next={...next,memories:[{id:`return-${key}`,type:'return',title:'留守番のあと',body,createdAt:now},...next.memories].slice(0,60)}}}return next}
const favorite=counts=>Object.entries(counts||{}).sort((a,b)=>b[1]-a[1])[0]?.[0]||null
export const recordPetting=(s,zone,now=Date.now())=>{const z=['head','body','tail'].includes(zone)?zone:'body',counts={head:Number(s.preferences?.touchCounts?.head||0),body:Number(s.preferences?.touchCounts?.body||0),tail:Number(s.preferences?.touchCounts?.tail||0)};counts[z]+=1;const gain=z==='tail'&&s.kind==='cat'?0:1;return{...s,bond:clamp(Number(s.bond||0)+gain),comfort:clamp(Number(s.comfort||0)+(gain?2:0)),totalPets:Number(s.totalPets||0)+1,lastPettedAt:now,preferences:{...s.preferences,touchCounts:counts,favoriteTouchZone:favorite(counts)}}}
export const feedPet=(s,food,now=Date.now())=>{const f=['daily','special','treat'].includes(food)?food:'daily',effects={daily:{fullness:54,energy:2,comfort:2,bond:1},special:{fullness:48,energy:3,comfort:5,bond:2},treat:{fullness:13,energy:2,comfort:4,bond:1}}[f],counts={daily:Number(s.preferences?.foodCounts?.daily||0),special:Number(s.preferences?.foodCounts?.special||0),treat:Number(s.preferences?.foodCounts?.treat||0)};counts[f]+=1;let next={...s,fullness:clamp(Number(s.fullness||0)+effects.fullness),energy:clamp(Number(s.energy||0)+effects.energy),comfort:clamp(Number(s.comfort||0)+effects.comfort),bond:clamp(Number(s.bond||0)+effects.bond),totalMeals:Number(s.totalMeals||0)+1,lastFedAt:now,debug:{...s.debug,forcedHunger:false},preferences:{...s.preferences,foodCounts:counts,favoriteFood:favorite(counts)}};const title=f==='treat'?'ひとくちのおやつ':'落ち着いた食事',body=f==='special'?`${s.petName}は何度か香りを確かめてから、いつもより夢中で食べました。`:f==='treat'?`${s.petName}は食べ終えたあと、まだ少し期待するようにこちらを見ました。`:`${s.petName}は食器の前で落ち着いて食べ、最後に口元をぺろりとしました。`;return addMemory(next,title,body,now,'meal')}
export const recordPlay=(s,now=Date.now())=>{let next={...s,totalPlays:Number(s.totalPlays||0)+1,lastPlayedAt:now,energy:clamp(Number(s.energy||0)-9),fullness:clamp(Number(s.fullness||0)-2),comfort:clamp(Number(s.comfort||0)+4),bond:clamp(Number(s.bond||0)+2)};const body=s.kind==='dog'?`${s.petName}はボールの動きを追い、戻ってくるたびにしっぽを大きく振りました。`:`${s.petName}はおもちゃの動きをじっと追い、最後に前足で押さえました。`;return addMemory(next,'夢中で遊んだ',body,now,'play')}
export const advanceVirtualTime=(s,ms)=>({...s,debug:{...s.debug,timeOffsetMs:Number(s?.debug?.timeOffsetMs||0)+Number(ms||0)}})
export const resetVirtualTime=s=>({...s,debug:{...s.debug,timeOffsetMs:0,forcedHunger:false,forcedSleep:false}})
export const setForcedHunger=(s,v=true)=>({...s,debug:{...s.debug,forcedHunger:Boolean(v)}})
export const setForcedSleep=(s,v=true)=>({...s,debug:{...s.debug,forcedSleep:Boolean(v)}})
export const updateRoutine=(s,r)=>({...s,routine:sanitizeRoutine(r)})
export const serializeState=s=>JSON.stringify(s)
export const parseState=(raw,now=Date.now())=>{const initial=createInitialState(now);if(!raw)return initial;try{const p=JSON.parse(raw);if(p.version!==APP_VERSION)return initial;return{...initial,...p,routine:sanitizeRoutine(p.routine),memories:Array.isArray(p.memories)?p.memories:[],preferences:{...initial.preferences,...(p.preferences||{}),touchCounts:{...initial.preferences.touchCounts,...(p.preferences?.touchCounts||{})},foodCounts:{...initial.preferences.foodCounts,...(p.preferences?.foodCounts||{})}},debug:{...initial.debug,...(p.debug||{})}}}catch{return initial}}
